 const repairVehicle=()=>{if(serviceLock.current||action.current||!nearbyGarage||telemetry.speed>2)return;const q=repairQuote(health,wallet,repairBudget);if(!q.cost)return;serviceLock.current=true;energyLocked.current=true;setServicing(true);setRepairPopup(false);setRepairPose({garage:nearbyGarage,bike:{x:telemetry.x,z:telemetry.z},started:performance.now()});for(const k of Object.keys(inputs.current) as InputKey[])inputs.current[k]=false;const id='REPAIR-'+Date.now();serviceTimer.current=window.setTimeout(()=>{const next=repair({...latest.current,health},repairBudget,id);setHealth(next.health??100);setCareer(next);persist(next);setRepairPose(null);setServicing(false);serviceLock.current=false;setEnergyNotice('Đã sửa xe · '+fmt(q.cost)+'đ')},5000)};
 const service=(rescue=false)=>{if(serviceLock.current||action.current||telemetry.speed>2||(!rescue&&!nearbyStation)||(rescue&&remaining>0))return;const amount=rescue?Math.min(budget,vehicle==='petrol'?11500:2000):budget;const q=quote(vehicle,remaining,wallet,amount,maxEnergy);if(!q.cost){setEnergyNotice('Không đủ tiền hoặc đã đầy');return}serviceLock.current=true;energyLocked.current=true;setServicing(true);setEnergyPopup(false);setServicePose(!rescue&&nearbyStation?{station:nearbyStation,bike:{x:telemetry.x,z:telemetry.z},heading:telemetry.heading,started:performance.now()}:null);setPhone(false);for(const k of Object.keys(inputs.current) as InputKey[])inputs.current[k]=false;const id='ENERGY-'+Date.now();serviceTimer.current=window.setTimeout(()=>{const next=purchase({...latest.current,remaining},amount,id);setRemaining(next.remaining);setCareer(next);persist(next);serviceLock.current=false;setServicing(false);setServicePose(null);setEnergyNotice('Đã tiếp năng lượng · '+fmt(q.cost)+'đ')},rescue?1500:4000)};
 const interact=()=>{if(serviceLock.current||energyPopup||repairPopup)return;if(!order||distanceTo>=10||telemetry.speed>2||action.current||lock.current!==stage||stage==='done')return;action.current={kind:stage,elapsed:0,cargo:cargoKind(order.kind,order.detail?.product)};audio.cargoSound(stage==='pickup');setBusy(true);setPhone(false);for(const k of Object.keys(inputs.current) as InputKey[])inputs.current[k]=false;};
 const completeDelivery=()=>{const a=action.current;if(!a||!order||lock.current!==a.kind)return;action.current=null;setBusy(false);if(a.kind==='pickup'){audio.cargoSound(false);lock.current='dropoff';setStage('dropoff')}else{lock.current='done';setStage('done');const before=snapshot();const next=settle({...before,stage:'done'},order);if(next!==before)setFeedback({id:++feedbackSeq.current,positive:true,amount:next.income.wallet-before.income.wallet});setXpNotice('+'+(next.xp-career.xp)+' XP'+(next.level>career.level?' · LÊN CẤP '+next.level+' · Thưởng '+fmt(next.income.wallet-career.income.wallet-order.fare-(next.ratings?.at(-1)?.tip??0))+'đ':''));const q=queue.current[0];if(q){queue.current=queue.current.slice(1);setQueued(queue.current);run.current=q.run;lock.current=q.stage;setStage(q.stage);setOrder(q.order);const resumed={...next,queue:queue.current,stage:q.stage,order:q.order,run:q.run};persist(resumed);setCareer(resumed)}else{run.current=null;persist(next);setCareer(next)}setBatch(next.batch)}};
 const accept=(o:Order)=>{if(Date.now()>=marketExpiry||!offers.some(p=>p.id===o.id)){setMarketNotice('Đơn đã hết hạn.');return}if(serviceLock.current||action.current||career.paid.includes(o.id)||o.id===order?.id||queue.current.some(q=>q.order.id===o.id)||(o.kind&&career.level<ORDER_TYPES[o.kind].level)||(o.kind==='vip'&&!vip))return;const used=(lock.current==='done'?0:order?.size??2)+queue.current.reduce((n,q)=>n+(q.order.size??2),0);if(used+(o.size??2)>2){setMarketNotice('Thùng hàng không đủ chỗ.');return}const nextRun=startRun(o);setMarketNotice('Đã nhận đơn');setXpNotice('');if(lock.current!=='done'){queue.current=[...queue.current,{order:o,stage:'pickup',run:nextRun}];setQueued(queue.current);persist(snapshot());return}run.current=nextRun;setNow(Date.now());lock.current='pickup';setOrder(o);setStage('pickup');persist({...snapshot(),order:o,stage:'pickup',run:nextRun});setPhone(false)};
 const switchDelivery=(id:string)=>{if(!order||!run.current||lock.current==='done'||action.current||serviceLock.current||Math.abs(telemetry.speed)>1)return;const q=queue.current.find(x=>x.order.id===id);if(!q)return;queue.current=queue.current.map(x=>x.order.id===id?{order,stage:lock.current as 'pickup'|'dropoff',run:run.current!}:x);setQueued(queue.current);run.current=q.run;lock.current=q.stage;setOrder(q.order);setStage(q.stage);persist({...snapshot(),order:q.order,stage:q.stage,run:q.run});setPhone(false)};
